        B.q("psm-p4-84", "psm-sprint-backlog", "A team keeps only the selected items in its Sprint Backlog. The Sprint Goal is in an email, and the plan is in people's heads. What is missing from its Sprint Backlog?", listOf("Nothing; the selected items alone make up the Sprint Backlog", "The Sprint Goal and an actionable plan for delivering the Increment", "The Definition of Done and the forecast of the Developers' capacity", "The Product Goal and the order of the remaining Product Backlog items"), setOf(1),
